import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { notificationAPI } from '../../api/endpoints';
import {
    FaBell,
    FaUserCircle,
    FaSignOutAlt,
    FaStore,
    FaUserShield,
    FaExchangeAlt,
    FaBars,
    FaCheckDouble,
    FaUserTie,
    FaUser
} from 'react-icons/fa';
import { IoNotificationsOutline } from 'react-icons/io5';
import toast from 'react-hot-toast';
import playNotificationSound from '../../utils/notificationSound';

const Navbar = ({ onToggleSidebar }) => {
    const navigate = useNavigate();
    const { user, logout, updateUser } = useAuth();
    const [notifications, setNotifications] = useState([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [showNotifications, setShowNotifications] = useState(false);
    const prevUnreadRef = useRef(null);

    useEffect(() => {
        if (user) {
            fetchNotifications(true);
            // Fast auto-polling for instant real-time notifications (every 4 seconds)
            const interval = setInterval(() => fetchNotifications(false), 4000);
            return () => clearInterval(interval);
        }
    }, [user]);

    const fetchNotifications = async (isInitial = false) => {
        try {
            const res = await notificationAPI.getAll();
            if (res.data?.success) {
                const list = res.data.data || [];
                const currentUnread = res.data.unreadCount || 0;

                // If not initial load and unread count increased, play ring chime and alert admin!
                if (!isInitial && prevUnreadRef.current !== null && currentUnread > prevUnreadRef.current) {
                    playNotificationSound();
                    const latest = list.find((n) => !n.is_read);
                    if (latest) {
                        toast(
                            (t) => (
                                <div
                                    style={{ cursor: 'pointer' }}
                                    onClick={() => {
                                        toast.dismiss(t.id);
                                        if (latest.link) navigate(latest.link);
                                    }}
                                >
                                    <div className="fw-bold small">{latest.title}</div>
                                    <div className="text-muted" style={{ fontSize: '0.78rem' }}>{latest.message}</div>
                                </div>
                            ),
                            {
                                icon: latest.type?.includes('maintenance') ? '🛠️' : '🔔',
                                duration: 8000,
                                style: {
                                    background: '#0f172a',
                                    color: '#f8fafc',
                                    border: '1px solid #38bdf8',
                                    borderRadius: '10px'
                                }
                            }
                        );
                    }
                }

                prevUnreadRef.current = currentUnread;
                setNotifications(list);
                setUnreadCount(currentUnread);
            }
        } catch (error) {
            // Silently handle
        }
    };

    const handleNotificationClick = async (n) => {
        try {
            await handleMarkAsRead(n.id);
            setShowNotifications(false);
            if (n.link) {
                navigate(n.link);
            }
        } catch (err) {
            console.error('Notification click error:', err);
        }
    };

    const handleMarkAsRead = async (id) => {
        try {
            await notificationAPI.markRead(id);
            setNotifications((prev) =>
                prev.map((n) => (n.id === id ? { ...n, is_read: true } : n))
            );
            setUnreadCount((prev) => Math.max(0, prev - 1));
            if (prevUnreadRef.current !== null) {
                prevUnreadRef.current = Math.max(0, prevUnreadRef.current - 1);
            }
        } catch (error) {
            console.error('Mark read error:', error);
        }
    };

    const handleMarkAllRead = async () => {
        try {
            await notificationAPI.markAllRead();
            setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
            setUnreadCount(0);
            prevUnreadRef.current = 0;
            toast.success('All notifications marked as read');
        } catch (error) {
            console.error('Mark all read error:', error);
        }
    };

    return (
        <header className="top-navbar">
            <div className="d-flex align-items-center gap-3">
                <button
                    className="btn btn-sm btn-outline-secondary d-lg-none"
                    onClick={onToggleSidebar}
                    aria-label="Toggle menu"
                >
                    <FaBars />
                </button>
                <div>
                    <h5 className="mb-0 fw-bold text-dark d-flex align-items-center gap-2">
                        <FaStore className="text-primary" />
                        Commercial Lease Hub
                    </h5>
                    <small className="text-muted">Enterprise Stall Management & Operations Platform</small>
                </div>
            </div>

            <div className="d-flex align-items-center gap-3">
                {/* Admin Secure Badge */}
                <div className="d-none d-md-flex align-items-center gap-2 bg-light px-3 py-1.5 rounded-pill border">
                    <FaUserShield className="text-primary" />
                    <span className="small fw-bold text-dark">Administrator Portal</span>
                </div>

                {/* Notifications Dropdown */}
                <div className="position-relative">
                    <button
                        className="btn btn-light position-relative p-2 rounded-circle border shadow-sm"
                        onClick={() => setShowNotifications(!showNotifications)}
                        aria-label="Notifications"
                    >
                        <FaBell className="text-secondary" />
                        {unreadCount > 0 && (
                            <span className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger">
                                {unreadCount}
                            </span>
                        )}
                    </button>

                    {showNotifications && (
                        <div
                            className="position-absolute end-0 mt-2 bg-white rounded-3 shadow-lg border p-0"
                            style={{ width: '340px', zIndex: 1050 }}
                        >
                            <div className="p-3 border-bottom d-flex justify-content-between align-items-center bg-light rounded-top-3">
                                <div className="d-flex align-items-center gap-2">
                                    <IoNotificationsOutline className="text-primary fw-bold" size={18} />
                                    <h6 className="mb-0 fw-bold">Live Notifications</h6>
                                </div>
                                {unreadCount > 0 && (
                                    <button
                                        className="btn btn-link btn-sm text-decoration-none p-0 text-primary"
                                        onClick={handleMarkAllRead}
                                    >
                                        <FaCheckDouble className="me-1" /> Mark all read
                                    </button>
                                )}
                            </div>
                            <div style={{ maxHeight: '320px', overflowY: 'auto' }}>
                                {notifications.length === 0 ? (
                                    <div className="p-4 text-center text-muted small">
                                        No recent system alerts. All operational.
                                    </div>
                                ) : (
                                    notifications.map((n) => (
                                        <div
                                            key={n.id}
                                            className={`p-3 border-bottom cursor-pointer transition ${
                                                !n.is_read ? 'bg-light' : ''
                                            }`}
                                            onClick={() => handleNotificationClick(n)}
                                        >
                                            <div className="d-flex justify-content-between align-items-start mb-1">
                                                <strong className="small text-dark">{n.title}</strong>
                                                {!n.is_read && (
                                                    <span className="badge bg-primary" style={{ fontSize: '0.65rem' }}>
                                                        NEW
                                                    </span>
                                                )}
                                            </div>
                                            <p className="small text-muted mb-0">{n.message}</p>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    )}
                </div>

                {/* User Profile Info & Logout */}
                <div className="d-flex align-items-center gap-2 ps-2 border-start">
                    <div className="stat-icon-wrapper bg-primary-light text-primary" style={{ width: '38px', height: '38px', fontSize: '1.2rem' }}>
                        <FaUserCircle />
                    </div>
                    <div className="d-none d-sm-block text-start">
                        <div className="fw-semibold text-dark small">{user?.name || 'Administrator'}</div>
                        <div className="text-muted" style={{ fontSize: '0.75rem' }}>{user?.email || 'rentastall@gmail.com'}</div>
                    </div>
                    <button
                        onClick={logout}
                        className="btn btn-sm btn-outline-danger ms-2 p-2 rounded-circle"
                        title="Sign Out"
                    >
                        <FaSignOutAlt />
                    </button>
                </div>
            </div>
        </header>
    );
};

export default Navbar;

import React from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';

const PrivateRoute = ({ children, roles = [] }) => {
    const { isAuthenticated, user, loading } = useAuth();

    if (loading) {
        return <div className="text-center mt-5">Loading...</div>;
    }

    if (!isAuthenticated) {
        return <Navigate to="/login" />;
    }

    // Check if user has required role
    if (roles.length > 0 && !roles.includes(user?.role)) {
        return <Navigate to="/dashboard" />;
    }

    return children;
};

export default PrivateRoute;

import React from 'react';
import { FaQrcode, FaPrint, FaTimes, FaStore, FaMapMarkerAlt, FaTag, FaExternalLinkAlt } from 'react-icons/fa';

const QRCodeModal = ({ stall, onClose }) => {
    if (!stall) return null;

    const qrData = encodeURIComponent(
        JSON.stringify({
            stallId: stall.id,
            stallNumber: stall.stall_number,
            location: stall.location,
            monthlyRent: stall.monthly_rent,
            status: stall.status,
            tenant: stall.tenant_name || 'Available'
        })
    );

    const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=240x240&data=${qrData}&color=1e293b`;

    const handlePrint = () => {
        window.print();
    };

    return (
        <div className="modal fade show d-block" style={{ backgroundColor: 'rgba(15, 23, 42, 0.6)' }} tabIndex="-1">
            <div className="modal-dialog modal-dialog-centered">
                <div className="modal-content border-0 shadow-lg rounded-4 overflow-hidden">
                    <div className="modal-header bg-dark text-white p-3 border-0">
                        <h6 className="modal-title fw-bold d-flex align-items-center gap-2">
                            <FaQrcode className="text-primary" /> Stall QR Identification Card
                        </h6>
                        <button type="button" className="btn-close btn-close-white" onClick={onClose} aria-label="Close"></button>
                    </div>

                    <div className="modal-body p-4 text-center">
                        {/* Printable Stall Identification Card */}
                        <div id="printable-qr-card" className="p-4 border rounded-4 bg-white shadow-sm position-relative">
                            <div className="d-flex align-items-center justify-content-between mb-3 border-bottom pb-2">
                                <div className="d-flex align-items-center gap-2">
                                    <FaStore className="text-primary fs-4" />
                                    <h5 className="fw-bold mb-0 text-dark">{stall.stall_number}</h5>
                                </div>
                                <span className={`badge-status badge-${stall.status}`}>
                                    {stall.status}
                                </span>
                            </div>

                            {/* QR Code Container */}
                            <div className="my-3 d-flex justify-content-center">
                                <div className="p-2 border rounded-3 bg-light shadow-sm">
                                    <img
                                        src={qrCodeUrl}
                                        alt={`QR Code for ${stall.stall_number}`}
                                        width={200}
                                        height={200}
                                        className="img-fluid rounded"
                                    />
                                </div>
                            </div>

                            <p className="small text-muted mb-3">
                                Scan with mobile camera to view stall lease details or submit a maintenance ticket.
                            </p>

                            <div className="bg-light p-3 rounded-3 text-start small border">
                                <div className="d-flex justify-content-between mb-1">
                                    <span className="text-muted"><FaMapMarkerAlt className="me-1" /> Location:</span>
                                    <span className="fw-semibold text-dark">{stall.location || 'N/A'}</span>
                                </div>
                                <div className="d-flex justify-content-between mb-1">
                                    <span className="text-muted"><FaTag className="me-1" /> Monthly Rent:</span>
                                    <span className="fw-bold text-success">₱{Number(stall.monthly_rent).toLocaleString()}/mo</span>
                                </div>
                                {stall.tenant_name && (
                                    <div className="d-flex justify-content-between">
                                        <span className="text-muted">Assigned Tenant:</span>
                                        <span className="fw-semibold text-primary">{stall.tenant_name}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    <div className="modal-footer bg-light p-3 border-0 d-flex justify-content-between">
                        <button type="button" className="btn btn-outline-secondary" onClick={onClose}>
                            Close
                        </button>
                        <button type="button" className="btn btn-primary d-flex align-items-center gap-2" onClick={handlePrint}>
                            <FaPrint /> Print Identification Card
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default QRCodeModal;

import React, { useState, useEffect } from 'react';
import { NavLink } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { maintenanceAPI } from '../../api/endpoints';
import {
    FaHome,
    FaStore,
    FaUsers,
    FaFileAlt,
    FaCreditCard,
    FaWrench,
    FaBullhorn,
    FaChartBar,
    FaUserCog,
    FaSignOutAlt
} from 'react-icons/fa';

const Sidebar = ({ isOpen, onClose }) => {
    const { logout, user, isAdmin } = useAuth();
    const [pendingMaintenance, setPendingMaintenance] = useState(0);

    useEffect(() => {
        const fetchPending = async () => {
            try {
                const res = await maintenanceAPI.getStats();
                if (res.data?.success && res.data.data?.pending !== undefined) {
                    setPendingMaintenance(res.data.data.pending);
                }
            } catch (e) {
                // Silently handle
            }
        };
        fetchPending();
        const interval = setInterval(fetchPending, 5000);
        return () => clearInterval(interval);
    }, []);

    const adminMenuItems = [
        { path: '/dashboard', icon: <FaHome />, label: 'Dashboard' },
        { path: '/stalls', icon: <FaStore />, label: 'Stalls & QR Codes' },
        { path: '/tenants', icon: <FaUsers />, label: 'Tenants Directory' },
        { path: '/applications', icon: <FaFileAlt />, label: 'Stall Applications' },
        { path: '/payments', icon: <FaCreditCard />, label: 'Billing & Payments' },
        { path: '/maintenance', icon: <FaWrench />, label: 'Maintenance Hub', badge: pendingMaintenance },
        { path: '/announcements', icon: <FaBullhorn />, label: 'Announcements' },
        { path: '/reports', icon: <FaChartBar />, label: 'Reports & Analytics' },
        ...(isAdmin ? [{ path: '/users', icon: <FaUserCog />, label: 'User Accounts' }] : []),
    ];

    return (
        <aside className={`app-sidebar ${isOpen ? 'show-mobile' : ''}`}>
            <div className="sidebar-header d-flex align-items-center justify-content-between">
                <div className="d-flex align-items-center gap-2">
                    <div className="bg-primary p-2 rounded-3 text-white">
                        <FaStore size={20} />
                    </div>
                    <div>
                        <h6 className="mb-0 fw-bold text-white">LeaseHub</h6>
                        <small className="text-muted" style={{ fontSize: '0.75rem' }}>
                            Admin Operations
                        </small>
                    </div>
                </div>
            </div>

            <nav className="sidebar-nav">
                <div className="text-uppercase text-muted px-3 mb-2" style={{ fontSize: '0.7rem', letterSpacing: '0.05em' }}>
                    Operations Menu
                </div>
                {adminMenuItems.map((item) => (
                    <NavLink
                        key={item.path}
                        to={item.path}
                        onClick={onClose}
                        className={({ isActive }) =>
                            `nav-link-custom ${isActive ? 'active' : ''}`
                        }
                    >
                        <span className="fs-5">{item.icon}</span>
                        <span>{item.label}</span>
                        {item.badge > 0 && (
                            <span className="badge bg-danger rounded-pill ms-auto px-2 py-1" style={{ fontSize: '0.7rem' }}>
                                {item.badge}
                            </span>
                        )}
                    </NavLink>
                ))}
            </nav>

            <div className="p-3 border-top border-secondary border-opacity-25">
                <div className="d-flex align-items-center justify-content-between p-2 rounded bg-dark bg-opacity-50">
                    <div className="d-flex align-items-center gap-2 overflow-hidden">
                        <div className="badge bg-primary text-capitalize">{user?.role || 'Admin'}</div>
                        <span className="text-white small text-truncate">{user?.name || 'Administrator'}</span>
                    </div>
                    <button
                        onClick={logout}
                        className="btn btn-sm btn-outline-danger p-1 rounded"
                        title="Sign Out"
                    >
                        <FaSignOutAlt />
                    </button>
                </div>
            </div>
        </aside>
    );
};

export default Sidebar;

